type Loader interface {
	Load([]Source) (Reader, error)
}
    Loader copies sources in defaults/file/environment/CLI order before sealing.

type Reader interface {
	Lookup(string) (string, bool)
}

type Source struct {
	Name   string
	Values map[string]string
}

package di // import "github.com/cymondez/pangolin-framework/kernel/di"

Package di defines the M0 provider contracts. A runtime container is delivered
in M1.

TYPES

type Builder interface {
	Provide(Provider) error
	Replace(Provider, string) error
}
    Builder cannot resolve services. Replace requires a nonempty reason.

type Cleanup func(context.Context) error

type Container interface {
	Resolver
	OpenScope(context.Context) (Scope, error)
	Close(context.Context) error
}

type Factory func(context.Context, Resolver) (any, Cleanup, error)

type Key[T any] struct {
	// Has unexported fields.
}
    Key preserves the service type at declaration sites without scanning
    objects.

func NewKey[T any](name string) Key[T]

func (k Key[T]) Name() string

func (k Key[T]) Type() reflect.Type

type Lifetime uint8

const (
	Singleton Lifetime = iota
	Transient
	Operation
)
type Provider struct {
	Key       Token
	Lifetime  Lifetime
	DependsOn []Token
	Factory   Factory
}

type Registry interface {
	Builder
	Seal(context.Context) (Container, error)
}

type Resolver interface {
	Resolve(context.Context, Token) (any, error)
}

type Scope interface {
	Resolver
	Close(context.Context) error
}

type Token interface {
	Name() string
	Type() reflect.Type
}
    Token identity is the pair (Name, Type); the registry rejects empty names.

package module // import "github.com/cymondez/pangolin-framework/kernel/module"

Package module defines module registration and lifecycle contracts, not a
runtime.

TYPES

type Builder interface {
	di.Builder
	SetDefault(string, string) error
}

type Dependency struct {
	Name              string
	VersionConstraint string
}

type Module struct {
	Name               string
	Version            string
	DependsOn          []Dependency
	RequiredScopeKinds []string
	PreConfigure       func(Builder) error
	Configure          func(Builder) error
	PostConfigure      func(Builder) error
	Start              func(context.Context, Runtime) error
	Stop               func(context.Context, Runtime) error
}

type Plan struct {
	Ordered []Module
	Layers  [][]string
}
    Plan is a detached snapshot, not a mutable handle into a live registry.

type Registry interface {
	Register(Module) error
	Plan() (Plan, error)
}

type Runtime interface {
	Services() di.Resolver
	Config() config.Reader
}
    Runtime is a sealed service/config view. It cannot register providers.

