package migration // import "github.com/cymondez/pangolin-framework/persistence/migration"

Package migration defines deployment-only migration ports. API startup never
invokes Runner.

CONSTANTS

const LockKey int64 = 0x70616e676f6c696e
    LockKey is shared by all modules in this application's database.


TYPES

type Lock interface {
	Release(context.Context) error
}
    Lock owns an exclusive PostgreSQL session; Release never releases another
    session's lock.

type Locker interface {
	Acquire(context.Context, int64) (Lock, error)
}

type ModuleMigrations struct {
	Module    string
	DependsOn []string
	Directory string
}

type Runner interface {
	Apply(context.Context, []ModuleMigrations) error
	CheckCompatibility(context.Context) error
}

github.com/cymondez/pangolin-framework/s.surface:
package scope // import "github.com/cymondez/pangolin-framework/security/scope"

Package scope defines neutral resource scope ports. Binding/admission are not
implemented in M0.

TYPES

type PrincipalRef struct {
	ID   string
	Kind string
}

type ScopeAdmitter interface {
	Admit(context.Context, ScopeBinding) (ScopeBinding, error)
}
    ScopeAdmitter returns the authoritative snapshot for a new top-level
    operation. It preserves Ref/Principal; RequiresNew reuses its parent's
    admitted snapshot.

type ScopeBinding struct {
	Ref               ScopeRef
	Principal         PrincipalRef
	AuthorityRevision string
}

type ScopeProvider interface {
	Kinds() []string
	Resolve(context.Context, PrincipalRef, ScopeRef) (ScopeBinding, error)
	Authorize(context.Context, ScopeBinding, string) error
}

type ScopeRef struct {
	TenantID string
	Kind     string
	ID       string
}

type ScopeResolver interface {
	Bind(context.Context, ScopeRef) (context.Context, error)
	Current(context.Context) (ScopeBinding, bool)
}
